export default function ThemeToggle({ theme, setTheme }) {
  return (
    <button
      className="px-3 py-1 border rounded dark:border-gray-600"
      onClick={() => setTheme((t) => (t === "dark" ? "light" : "dark"))}
    >
      {theme === "dark" ? "Light Mode" : "Dark Mode"}
    </button>
  );
}
